package com.nextfeet.nextfeet.service; import java.util.*; import org.springframework.stereotype.Service; import com.nextfeet.nextfeet.model.Categoria; import com.nextfeet.nextfeet.repository.CategoriaDAO; @Service public class CategoriaServiceImpl implements CategoriaService {private final CategoriaDAO dao; public CategoriaServiceImpl(CategoriaDAO dao){this.dao=dao;} public List<Categoria> listar(){return dao.listar();} public Categoria obtener(Integer id){return dao.obtener(id);} public void crear(Categoria c){dao.crear(c);} public void actualizar(Categoria c){dao.actualizar(c);} public void desactivar(Integer id){dao.desactivar(id);}}